import { MutableRefObject, useMemo, useRef } from "react"
import { useFrame } from "@react-three/fiber"
import * as THREE from "three"

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

const clamp01 = (v: number) => Math.min(1, Math.max(0, v))
/** Maps p from [a, b] to [0, 1], clamped. */
const range = (p: number, a: number, b: number) => clamp01((p - a) / (b - a))
const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)
const lerp = THREE.MathUtils.lerp

/**
 * The petal from the brand mandala (mandala_dahlia.svg), flipped so the tip points +Y
 * and normalised to length 1.
 */
const makePetalShape = () => {
    const s = new THREE.Shape()
    s.moveTo(0, 44)
    s.bezierCurveTo(0, 44, -11.4, 33.6, -9.7, 19.1)
    s.bezierCurveTo(-8.5, 8.4, 0, 0, 0, 0)
    s.bezierCurveTo(0, 0, 8.5, 8.4, 9.7, 19.1)
    s.bezierCurveTo(11.4, 33.6, 0, 44, 0, 44)
    return s
}

/* ------------------------------------------------------------------ */
/* Dahlia                                                              */
/* ------------------------------------------------------------------ */

type Layer = {
    count: number
    scale: number
    offsetDeg: number
    closed: number   // tilt toward camera when in bud (radians)
    open: number     // tilt when fully bloomed
    delay: number    // bloom start offset in scroll progress
    color: string
    emissive: string
    emissiveIntensity: number
}

const LAYERS: Layer[] = [
    { count: 16, scale: 1.7, offsetDeg: 0, closed: 1.35, open: 0.12, delay: 0, color: "#34151D", emissive: "#e91e62", emissiveIntensity: 0.08 },
    { count: 16, scale: 1.25, offsetDeg: 11.25, closed: 1.45, open: 0.45, delay: 0.05, color: "#4F2934", emissive: "#ff3d8b", emissiveIntensity: 0.14 },
    { count: 8, scale: 0.8, offsetDeg: 22.5, closed: 1.5, open: 0.85, delay: 0.1, color: "#6b2a4a", emissive: "#ff7a59", emissiveIntensity: 0.3 },
]

const Dahlia = ({ progress }: { progress: MutableRefObject<number> }) => {
    const group = useRef<THREE.Group>(null)
    const petals = useRef<(THREE.Group | null)[]>([])

    const { petalGeo, outlineGeo } = useMemo(() => {
        const shape = makePetalShape()
        const petalGeo = new THREE.ExtrudeGeometry(shape, {
            depth: 0.6,
            bevelEnabled: true,
            bevelThickness: 0.6,
            bevelSize: 0.5,
            bevelSegments: 3,
            curveSegments: 24,
        })
        petalGeo.scale(1 / 44, 1 / 44, 1 / 44)
        const outlineGeo = new THREE.BufferGeometry().setFromPoints(shape.getPoints(48))
        outlineGeo.scale(1 / 44, 1 / 44, 1 / 44)
        outlineGeo.translate(0, 0, 0.035)
        return { petalGeo, outlineGeo }
    }, [])

    const materials = useMemo(
        () =>
            LAYERS.map(
                (l) =>
                    new THREE.MeshStandardMaterial({
                        color: l.color,
                        emissive: l.emissive,
                        emissiveIntensity: l.emissiveIntensity,
                        metalness: 0.55,
                        roughness: 0.3,
                        side: THREE.DoubleSide,
                    })
            ),
        []
    )

    const outlineMat = useMemo(
        () =>
            new THREE.LineBasicMaterial({
                color: "#EEECE9",
                transparent: true,
                opacity: 0.55,
                blending: THREE.AdditiveBlending,
                depthWrite: false,
            }),
        []
    )

    // Flat list of petals so useFrame can iterate quickly.
    const items = useMemo(() => {
        const out: { layer: number; angle: number; i: number }[] = []
        LAYERS.forEach((l, li) => {
            for (let i = 0; i < l.count; i++) {
                out.push({ layer: li, angle: THREE.MathUtils.degToRad(l.offsetDeg + (360 / l.count) * i), i })
            }
        })
        return out
    }, [])

    useFrame((state) => {
        const p = progress.current
        const t = state.clock.elapsedTime

        items.forEach((it, idx) => {
            const g = petals.current[idx]
            if (!g) return
            const l = LAYERS[it.layer]
            const bloom = easeInOut(range(p, 0.12 + l.delay, 0.45 + l.delay))
            const breathe = Math.sin(t * 0.9 + it.i * 0.6 + it.layer) * 0.04
            g.rotation.x = lerp(l.closed, l.open, bloom) + breathe
        })

        if (group.current) {
            const exit = easeInOut(range(p, 0.55, 0.85))
            // Start tipped back so the closed bud reads in profile, then turn to face the viewer.
            group.current.rotation.x = lerp(-1.0, 0, easeInOut(range(p, 0, 0.4)))
            group.current.rotation.z = t * 0.06 + p * 1.4
            group.current.rotation.y = exit * 0.9
            // Hero: bud sits below the headline. Chapters 2-3: flower shifts left of the
            // right-aligned copy. Exit: it swings further left as the camera passes.
            const rise = easeInOut(range(p, 0.05, 0.3))
            const aside = easeInOut(range(p, 0.18, 0.35))
            // Portrait screens have little horizontal room, so shrink the sideways moves.
            const sideK = Math.min(1, state.viewport.aspect / 1.4)
            group.current.position.set((lerp(0, -1.7, aside) - 2.4 * exit) * sideK, lerp(-2.5, 0, rise) - 0.4 * exit, 0)
            const s = lerp(1.1, 1.05, easeInOut(range(p, 0.1, 0.5)))
            group.current.scale.setScalar(s)
        }
    })

    return (
        <group ref={group}>
            {items.map((it, idx) => {
                const l = LAYERS[it.layer]
                return (
                    <group key={idx} rotation={[0, 0, it.angle]}>
                        <group ref={(el) => (petals.current[idx] = el)} scale={l.scale}>
                            <mesh geometry={petalGeo} material={materials[it.layer]} />
                            <lineLoop geometry={outlineGeo} material={outlineMat} />
                        </group>
                    </group>
                )
            })}
            {/* glowing heart */}
            <mesh>
                <sphereGeometry args={[0.18, 32, 32]} />
                <meshBasicMaterial color="#ffb38a" />
            </mesh>
            <pointLight color="#ff7a59" intensity={6} distance={4} />
        </group>
    )
}

/* ------------------------------------------------------------------ */
/* Silk ribbons (animated in the vertex shader)                        */
/* ------------------------------------------------------------------ */

const ribbonVert = /* glsl */ `
    uniform float uTime;
    uniform float uAmp;
    uniform float uPhase;
    uniform float uTwist;
    varying vec2 vUv;
    void main() {
        vUv = uv;
        float x = position.x;
        float a = x * uTwist + uTime * 0.35 + uPhase;
        vec3 n = vec3(0.0, cos(a), sin(a));
        vec3 center = vec3(
            x,
            sin(x * 0.32 + uTime * 0.4 + uPhase) * uAmp,
            cos(x * 0.21 + uTime * 0.3 + uPhase * 1.3) * uAmp * 1.3
        );
        vec3 pos = center + n * position.y;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
`

const ribbonFrag = /* glsl */ `
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uColorC;
    uniform float uOpacity;
    varying vec2 vUv;
    void main() {
        vec3 c = mix(uColorA, uColorB, smoothstep(0.0, 0.5, vUv.x));
        c = mix(c, uColorC, smoothstep(0.5, 1.0, vUv.x));
        float d = abs(vUv.y - 0.5) * 2.0;           // 0 centre, 1 edge
        float silk = pow(d, 3.0) * 0.9 + 0.12;      // bright edges, sheer middle
        float ends = smoothstep(0.0, 0.18, vUv.x) * smoothstep(1.0, 0.82, vUv.x);
        gl_FragColor = vec4(c * (0.6 + silk * 1.4), uOpacity * ends * (0.25 + silk * 0.75));
    }
`

type RibbonProps = {
    position: [number, number, number]
    rotation?: [number, number, number]
    width: number
    amp: number
    phase: number
    twist: number
    colors: [string, string, string]
    opacity: number
}

const Ribbon = ({ position, rotation = [0, 0, 0], width, amp, phase, twist, colors, opacity }: RibbonProps) => {
    const mat = useRef<THREE.ShaderMaterial>(null)
    const uniforms = useMemo(
        () => ({
            uTime: { value: 0 },
            uAmp: { value: amp },
            uPhase: { value: phase },
            uTwist: { value: twist },
            uColorA: { value: new THREE.Color(colors[0]) },
            uColorB: { value: new THREE.Color(colors[1]) },
            uColorC: { value: new THREE.Color(colors[2]) },
            uOpacity: { value: opacity * 0.7 },
        }),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        []
    )
    useFrame((state) => {
        if (mat.current) mat.current.uniforms.uTime.value = state.clock.elapsedTime
    })
    return (
        <mesh position={position} rotation={rotation} frustumCulled={false}>
            <planeGeometry args={[26, width, 260, 6]} />
            <shaderMaterial
                ref={mat}
                vertexShader={ribbonVert}
                fragmentShader={ribbonFrag}
                uniforms={uniforms}
                transparent
                depthWrite={false}
                blending={THREE.AdditiveBlending}
                side={THREE.DoubleSide}
            />
        </mesh>
    )
}

const Ribbons = ({ progress, lite }: { progress: MutableRefObject<number>; lite: boolean }) => {
    const group = useRef<THREE.Group>(null)
    useFrame(() => {
        if (group.current) group.current.rotation.z = -0.25 + progress.current * 0.5
    })
    return (
        <group ref={group}>
            <Ribbon position={[0, -1.2, -2.5]} width={1.4} amp={1.1} phase={0} twist={0.28} colors={["#ff9a5a", "#e91e62", "#4a5cff"]} opacity={0.55} />
            <Ribbon position={[0, 0.6, -4]} rotation={[0, 0, 0.35]} width={1.8} amp={1.4} phase={2.1} twist={0.2} colors={["#7a2cff", "#ff2d95", "#ff9a5a"]} opacity={0.45} />
            {!lite && (
                <>
                    <Ribbon position={[0, -2.4, -1]} rotation={[0, 0, -0.2]} width={0.9} amp={0.9} phase={4.2} twist={0.35} colors={["#4a5cff", "#b02cff", "#ff2d95"]} opacity={0.5} />
                    <Ribbon position={[0, 2.2, -6]} rotation={[0, 0, -0.15]} width={2.4} amp={1.8} phase={1.3} twist={0.15} colors={["#e91e62", "#4a5cff", "#7a2cff"]} opacity={0.3} />
                </>
            )}
        </group>
    )
}

/* ------------------------------------------------------------------ */
/* Eclipse ring (the "portal" at the end of the scroll)                 */
/* ------------------------------------------------------------------ */

const ringFrag = /* glsl */ `
    uniform float uOpacity;
    varying vec2 vUv;
    void main() {
        float a = vUv.x; // around the ring
        vec3 warm = vec3(1.0, 0.62, 0.38);
        vec3 pink = vec3(0.91, 0.12, 0.38);
        vec3 blue = vec3(0.29, 0.36, 1.0);
        vec3 c = mix(warm, pink, smoothstep(0.1, 0.45, a));
        c = mix(c, blue, smoothstep(0.45, 0.8, a));
        c = mix(c, warm, smoothstep(0.85, 1.0, a));
        gl_FragColor = vec4(c, uOpacity);
    }
`
const ringVert = /* glsl */ `
    varying vec2 vUv;
    void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
`

const EclipseRing = ({ progress }: { progress: MutableRefObject<number> }) => {
    const group = useRef<THREE.Group>(null)
    const core = useMemo(() => ({ uOpacity: { value: 1 } }), [])
    const halo = useMemo(() => ({ uOpacity: { value: 0.18 } }), [])
    useFrame((state) => {
        if (!group.current) return
        group.current.rotation.z = state.clock.elapsedTime * 0.08
        const reveal = easeInOut(range(progress.current, 0.4, 0.75))
        core.uOpacity.value = reveal
        halo.uOpacity.value = 0.18 * reveal
    })
    return (
        <group ref={group} position={[0.6, 0.3, -8]}>
            <mesh>
                <torusGeometry args={[3.2, 0.018, 16, 256]} />
                <shaderMaterial vertexShader={ringVert} fragmentShader={ringFrag} uniforms={core} transparent depthWrite={false} blending={THREE.AdditiveBlending} />
            </mesh>
            <mesh>
                <torusGeometry args={[3.2, 0.14, 16, 256]} />
                <shaderMaterial vertexShader={ringVert} fragmentShader={ringFrag} uniforms={halo} transparent depthWrite={false} blending={THREE.AdditiveBlending} />
            </mesh>
        </group>
    )
}

/* ------------------------------------------------------------------ */
/* Dotted orbits + floating dust                                       */
/* ------------------------------------------------------------------ */

const Dust = ({ count }: { count: number }) => {
    const ref = useRef<THREE.Points>(null)
    const positions = useMemo(() => {
        const arr = new Float32Array(count * 3)
        for (let i = 0; i < count; i++) {
            arr[i * 3] = (Math.random() - 0.5) * 22
            arr[i * 3 + 1] = (Math.random() - 0.5) * 14
            arr[i * 3 + 2] = -Math.random() * 22 + 6
        }
        return arr
    }, [count])
    useFrame((state) => {
        if (ref.current) ref.current.rotation.y = state.clock.elapsedTime * 0.01
    })
    return (
        <points ref={ref}>
            <bufferGeometry>
                <bufferAttribute attach="attributes-position" args={[positions, 3]} />
            </bufferGeometry>
            <pointsMaterial size={0.035} color="#ffb38a" transparent opacity={0.7} depthWrite={false} blending={THREE.AdditiveBlending} />
        </points>
    )
}

const DottedOrbit = ({ radius, from, to, position, rotation }: { radius: number; from: number; to: number; position: [number, number, number]; rotation: [number, number, number] }) => {
    const positions = useMemo(() => {
        const n = 42
        const arr = new Float32Array(n * 3)
        for (let i = 0; i < n; i++) {
            const a = lerp(from, to, i / (n - 1))
            arr[i * 3] = Math.cos(a) * radius
            arr[i * 3 + 1] = Math.sin(a) * radius
            arr[i * 3 + 2] = 0
        }
        return arr
    }, [radius, from, to])
    return (
        <points position={position} rotation={rotation}>
            <bufferGeometry>
                <bufferAttribute attach="attributes-position" args={[positions, 3]} />
            </bufferGeometry>
            <pointsMaterial size={0.06} color="#ff9fb8" transparent opacity={0.85} depthWrite={false} blending={THREE.AdditiveBlending} />
        </points>
    )
}

/* ------------------------------------------------------------------ */
/* Camera rig                                                          */
/* ------------------------------------------------------------------ */

const CameraRig = ({ progress }: { progress: MutableRefObject<number> }) => {
    const look = useMemo(() => new THREE.Vector3(), [])
    useFrame((state) => {
        const p = progress.current
        const cam = state.camera
        const approach = easeInOut(range(p, 0, 0.5))
        const dive = easeInOut(range(p, 0.58, 1))
        // Back the camera off on portrait screens so the bloomed flower still fits the width.
        const aspect = state.viewport.aspect
        const fit = aspect < 1 ? lerp(1, 1.8, clamp01((1 - aspect) / 0.55)) : 1
        const z = lerp(lerp(11 * fit, 5.2 * fit, approach), -11, dive)
        const x = Math.sin(p * Math.PI) * 0.9 + state.pointer.x * 0.35
        const y = state.pointer.y * 0.25 + dive * 0.3
        cam.position.x += (x - cam.position.x) * 0.06
        cam.position.y += (y - cam.position.y) * 0.06
        cam.position.z = z
        look.set(0.6 * dive, 0.3 * dive, z - 10)
        cam.lookAt(look)
    })
    return null
}

/* ------------------------------------------------------------------ */
/* Scene                                                               */
/* ------------------------------------------------------------------ */

type SceneProps = {
    /** Raw scroll progress 0..1 written by the page. */
    target: MutableRefObject<number>
    lite: boolean
}

const DahliaScene = ({ target, lite }: SceneProps) => {
    // Smoothed copy of the scroll progress so motion glides instead of stepping.
    const progress = useRef(target.current)
    useFrame((_, dt) => {
        const k = 1 - Math.exp(-5 * Math.min(dt, 0.1))
        progress.current += (target.current - progress.current) * k
    }, -1)

    return (
        <>
            <ambientLight intensity={0.25} />
            <pointLight position={[-4, 3, 4]} color="#ff2d95" intensity={30} />
            <pointLight position={[4, -2, 3]} color="#4a5cff" intensity={30} />
            <directionalLight position={[2, 4, 6]} color="#ffd2b0" intensity={0.8} />

            <CameraRig progress={progress} />
            <Dahlia progress={progress} />
            <Ribbons progress={progress} lite={lite} />
            <EclipseRing progress={progress} />
            <DottedOrbit radius={4.2} from={2.2} to={3.6} position={[1, 0.5, -1.5]} rotation={[0.2, 0.3, 0]} />
            <DottedOrbit radius={3.4} from={-0.6} to={0.9} position={[-1, -0.5, -5]} rotation={[-0.3, 0.2, 0.4]} />
            <Dust count={lite ? 250 : 600} />
        </>
    )
}

export default DahliaScene
