import { ReactNode, useRef, useState } from "react"
import { Canvas } from "@react-three/fiber"
import { motion, MotionValue, useMotionValueEvent, useScroll, useTransform } from "framer-motion"
import { useInView } from "react-intersection-observer"
import ButtonScribble from "../ButtonScribble/ButtonScribble"
import DahliaScene from "./DahliaScene"
import "./dahlia-scroll-3d.scss"

const BG_1 = `${process.env.PUBLIC_URL}/images/backgrounds/neon-orbital-silk-waves.webp`
const BG_2 = `${process.env.PUBLIC_URL}/images/backgrounds/cosmic-magenta-ribbon-eclipse.webp`

const supportsWebGL = () => {
    try {
        const c = document.createElement("canvas")
        return !!(window.WebGLRenderingContext && (c.getContext("webgl2") || c.getContext("webgl")))
    } catch {
        return false
    }
}

const prefersReducedMotion = () =>
    typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches

/* ------------------------------------------------------------------ */
/* Text chapters that fade in/out over a slice of the scroll           */
/* ------------------------------------------------------------------ */

type ChapterProps = {
    progress: MotionValue<number>
    /** [fadeInStart, fullyVisible, startFadeOut, gone] in scroll progress */
    window: [number, number, number, number]
    align?: "center" | "left" | "right"
    children: ReactNode
}

const Chapter = ({ progress, window: w, align = "center", children }: ChapterProps) => {
    const opacity = useTransform(progress, w, [0, 1, 1, 0])
    const y = useTransform(progress, w, [40, 0, 0, -40])
    return (
        <motion.div className={`d3-chapter d3-chapter--${align}`} style={{ opacity, y }}>
            <div className="d3-chapter_inner">{children}</div>
        </motion.div>
    )
}

const ChapterContent = () => ({
    hero: (
        <>
            <p className="d3-eyebrow">Black Dahlia Creative</p>
            <h1 className="d3-title">Design with edge.<br />Style with soul.</h1>
            <p className="d3-scroll-hint">Scroll to bloom</p>
        </>
    ),
    bloom: (
        <>
            <p className="d3-eyebrow">Brand identity</p>
            <h2 className="d3-heading">Every brand starts as a bud.</h2>
            <p className="d3-text">We shape the strategy, the story and the look until it opens into something unmistakably yours.</p>
        </>
    ),
    craft: (
        <>
            <p className="d3-eyebrow">What we do</p>
            <h2 className="d3-heading">Branding · Web design · Creative direction</h2>
            <p className="d3-text">Boutique work for the bold, the soulful, and the ones who dare to stand apart.</p>
        </>
    ),
    portal: (
        <>
            <h2 className="d3-heading">Step through.</h2>
            <div className="d3-cta">
                <ButtonScribble className="primaryBtn" to={"/portfolio"} scribbleShift="50px">
                    Explore the Portfolio
                </ButtonScribble>
                <ButtonScribble
                    className="primaryBtn-vr1"
                    to={"/contact"}
                    scribbleShift="50px"
                    buttonBg="var(--black-dahlia-white)"
                    backColor="var(--alternative-black)"
                    lineColor="var(--alternative-black)"
                >
                    Start your creative journey
                </ButtonScribble>
            </div>
        </>
    ),
})

/* ------------------------------------------------------------------ */
/* Main component                                                      */
/* ------------------------------------------------------------------ */

const DahliaScroll3D = () => {
    const sectionRef = useRef<HTMLElement>(null)
    const progressRef = useRef(0)
    const [mode] = useState<"3d" | "static">(() => (prefersReducedMotion() || !supportsWebGL() ? "static" : "3d"))
    const [lite] = useState(() => window.innerWidth < 800)
    const content = ChapterContent()

    const { scrollYProgress } = useScroll({ target: sectionRef, offset: ["start start", "end end"] })
    useMotionValueEvent(scrollYProgress, "change", (v) => (progressRef.current = v))

    // Backdrop: slow push-in, then crossfade to the eclipse image for the finale.
    const bgScale = useTransform(scrollYProgress, [0, 1], [1.05, 1.35])
    const bg2Opacity = useTransform(scrollYProgress, [0.5, 0.75], [0, 1])

    // Stop rendering when the section is off screen.
    const { ref: viewRef, inView } = useInView({ threshold: 0 })

    if (mode === "static") {
        return (
            <section id="Dahlia3D" className="d3-static" style={{ backgroundImage: `url(${BG_1})` }}>
                <div className="d3-static_block">{content.hero}</div>
                <div className="d3-static_block">{content.bloom}</div>
                <div className="d3-static_block">{content.craft}</div>
                <div className="d3-static_block">{content.portal}</div>
            </section>
        )
    }

    return (
        <section id="Dahlia3D" ref={sectionRef}>
            <div className="d3-sticky" ref={viewRef}>
                <motion.div className="d3-backdrop" style={{ backgroundImage: `url(${BG_1})`, scale: bgScale }} />
                <motion.div className="d3-backdrop" style={{ backgroundImage: `url(${BG_2})`, scale: bgScale, opacity: bg2Opacity }} />
                <div className="d3-vignette" />

                <Canvas
                    className="d3-canvas"
                    dpr={[1, lite ? 1.5 : 2]}
                    camera={{ position: [0, 0, 11], fov: 45, near: 0.1, far: 100 }}
                    gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
                    frameloop={inView ? "always" : "never"}
                >
                    <DahliaScene target={progressRef} lite={lite} />
                </Canvas>

                <Chapter progress={scrollYProgress} window={[-1, 0, 0.1, 0.17]}>{content.hero}</Chapter>
                <Chapter progress={scrollYProgress} window={[0.2, 0.27, 0.4, 0.47]} align="right">{content.bloom}</Chapter>
                <Chapter progress={scrollYProgress} window={[0.52, 0.58, 0.68, 0.74]} align="right">{content.craft}</Chapter>
                <Chapter progress={scrollYProgress} window={[0.86, 0.93, 2, 3]}>{content.portal}</Chapter>
            </div>
        </section>
    )
}

export default DahliaScroll3D
